from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 8

    corner_right = grid[0].index(0) > (w - 1) // 2
    vertical = h > w
    span = min(h, w)
    out_width = span if vertical == corner_right else span - 2

    def runs(indices):
        groups = []
        for x in indices:
            if not groups or x != groups[-1][-1] + 1:
                groups.append([x])
            else:
                groups[-1].append(x)
        return groups

    def fit_rows(rows):
        fitted = []
        for row in rows:
            if len(row) > out_width:
                fitted.append(row[:out_width])
            else:
                left = (out_width - len(row)) // 2
                fitted.append([bg] * left + row + [bg] * (out_width - len(row) - left))
        return fitted

    output = []

    if not vertical:
        core_cols = range(1, w - 1)
        active_rows = [
            r for r in range(1, h - 1)
            if any(grid[r][c] != bg for c in core_cols)
        ]

        for band in runs(active_rows):
            active_cols = [
                c for c in core_cols
                if any(grid[r][c] != bg for r in band)
            ]
            col_groups = runs(active_cols)
            if corner_right:
                col_groups.reverse()

            for cols in col_groups:
                piece = [[grid[r][c] for c in cols] for r in band]
                output.extend(fit_rows(piece))

    else:
        core_cols = list(range(1, w - 1))
        active_cols = [
            c for c in core_cols
            if any(grid[r][c] != bg for r in range(1, h))
        ]
        lanes = runs(active_cols)
        if corner_right:
            lanes.reverse()

        for lane in lanes:
            units = []
            for r in range(2, h - 1, 2):
                unit = [[grid[rr][c] for c in lane] for rr in (r, r + 1)]
                active = any(v != bg for row in unit for v in row)

                vals = [v for row in unit for v in row
                        if v not in (bg, 0, 1, 2)]
                if not vals:
                    vals = [v for row in unit for v in row if v not in (bg, 0)]

                counts = Counter(vals)
                if counts:
                    most = max(counts.values())
                    candidates = [v for v, n in counts.items() if n == most]
                else:
                    candidates = []

                units.append((r, unit, active, candidates))

            # Resolve tied dominant colors using the nearest unambiguous
            # neighboring row-pair in the same lane.
            i = 0
            while i < len(units):
                if not units[i][2]:
                    i += 1
                    continue

                j = i
                while j < len(units) and units[j][2]:
                    j += 1

                segment = units[i:j]
                bases = []
                for k, (_, _, _, candidates) in enumerate(segment):
                    if len(candidates) == 1:
                        bases.append(candidates[0])
                        continue

                    prev = None
                    for p in range(k - 1, -1, -1):
                        if len(segment[p][3]) == 1:
                            prev = segment[p][3][0]
                            break

                    nxt = None
                    for p in range(k + 1, len(segment)):
                        if len(segment[p][3]) == 1:
                            nxt = segment[p][3][0]
                            break

                    if candidates:
                        if nxt in candidates:
                            bases.append(nxt)
                        elif prev in candidates:
                            bases.append(prev)
                        elif nxt is not None:
                            bases.append(nxt)
                        elif prev is not None:
                            bases.append(prev)
                        else:
                            bases.append(candidates[-1])
                    else:
                        bases.append(nxt if nxt is not None else prev)

                # Fill any remaining unclassified units from their neighbors.
                for k in range(len(bases)):
                    if bases[k] is None:
                        replacement = next((bases[p] for p in range(k + 1, len(bases))
                                            if bases[p] is not None), None)
                        if replacement is None:
                            replacement = next((bases[p] for p in range(k - 1, -1, -1)
                                                if bases[p] is not None), None)
                        bases[k] = replacement

                # Each run of row-pairs with the same base color is one piece.
                start = 0
                while start < len(segment):
                    end = start + 1
                    while end < len(segment) and bases[end] == bases[start]:
                        end += 1

                    first_r = segment[start][0]
                    last_r = segment[end - 1][0] + 1
                    piece = [grid[r][c] for r in range(first_r, last_r + 1)
                             for c in lane]
                    piece = [
                        [grid[r][c] for c in lane]
                        for r in range(first_r, last_r + 1)
                    ]

                    # Rotate the vertical piece 90 degrees counterclockwise.
                    rotated = [
                        [piece[r][c] for r in range(len(piece))]
                        for c in range(len(lane) - 1, -1, -1)
                    ]
                    output.extend(fit_rows(rotated))
                    start = end

